package com.luncher; import android.Manifest; import android.content.pm.PackageManager; import android.os.Bundle; import android.os.Environment; import android.os.StatFs; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; import androidx.core.app.ActivityCompat; import androidx.core.content.ContextCompat; class FileManagerActivity:AppCompatActivity(){override fun onCreate(s:Bundle?){super.onCreate(s); try{setContentView(R.layout.activity_files); val tvUsed=findViewById<TextView>(R.id.tvUsed); val tvRem=findViewById<TextView>(R.id.tvRemaining); val tvPct=findViewById<TextView>(R.id.tvPercent); try{val stat=StatFs(Environment.getDataDirectory().path); val total=stat.totalBytes; val free=stat.availableBytes; val used=total-free; val pct=(used*100/total).toInt(); tvUsed?.text=String.format("%.1f GB / %.0f GB used",used/1e9,total/1e9); tvRem?.text=String.format("Remaining: %.1f GB",free/1e9); tvPct?.text=pct.toString()+"%"}catch(_:Exception){}; if(ContextCompat.checkSelfPermission(this,Manifest.permission.READ_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(this,arrayOf(Manifest.permission.READ_EXTERNAL_STORAGE),1)}}catch(e:Exception){val tv=TextView(this); tv.text="Files erreur: "+e.message; setContentView(tv)}}}